class LearningScreen extends StatelessWidget{const LearningScreen({super.key});static const lessons=[('Western tropical zodiac','A symbolic framework. Sun-sign readings are generalized editorial content, not personal birth-chart calculations.'),('The four elements','Fire, earth, air and water are traditional symbolic groupings, not personality tests.'),('The three modalities','Cardinal, fixed and mutable describe symbolic approaches to beginnings, continuity and adaptation.'),('Planets and glyphs','Signs have traditional planetary associations. Rulership conventions vary between astrological schools.'),('Chart vocabulary','AstroDaily does not calculate rising signs, houses or natal planetary placements.'),('Retrogrades and evidence','Retrograde is apparent motion as viewed from Earth. Astrological meanings are symbolic and are not scientifically established predictions.'),('A short history','Zodiac traditions developed across many cultures and changed over time; modern Western tropical astrology is one particular tradition.')];@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Astrology learning')),body:ListView(padding:const EdgeInsets.all(20),children:[const PageHeader('Learn the language',subtitle:'Tradition, history and evidence—kept distinct.'),for(final l in lessons)Card(child:ExpansionTile(title:Text(l.$1),children:[Padding(padding:const EdgeInsets.fromLTRB(16,0,16,18),child:Text(l.$2))])),const DisclaimerCard()]));}
